return ['domain'=>'tag-groups','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'da-DK','project-id-version'=>'Tag Groups 2.1.2','pot-creation-date'=>'2026-06-15T12:41:40+00:00','po-revision-date'=>'2026-06-15 13:18+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Tag Groups'=>'Tag-Groups','https://wordpress.org/plugins/tag-groups/'=>'https://wordpress.org/plugins/tag-groups/','Tag Groups allows you to organize your WordPress taxonomy terms and show them in clouds, tabs, accordions, tables, lists and much more.'=>'Tag-Groups giver dig mulighed for at organisere dine WordPress taxonomi termer og vise dem i skyer, faner, akordeoner, tabeller, lister og meget mere.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','Home'=>'Hjem','Taxonomies'=>'Taxonomier','Front End'=>'Front End','Back End'=>'Back End','First Steps'=>'Første skridt','Setup Wizard'=>'Opsætningsguide','Settings'=>'Indstillinger','Tag Group Admin'=>'Tag Group Admin','The term has been removed from all groups.'=>'Termen er blevet fjernet fra alle grupper.','Edit this item inline'=>'Rediger dette element inline','Quick&nbsp;Edit'=>'Hurtig&nbsp;redigering','Please <a %s>click here to run the migration routines</a> to make sure we have migrated all tags.'=>'Bitte <a %s>klik her for at køre migrationsrutinerne</a> for at sikre, at vi har migreret alle tags.','Your settings/groups and your terms have been exported. Please download the resulting files with right-click or ctrl-click:'=>'Dine indstillinger/grupper og dine termer er blevet eksporteret. Download venligst de resulterende filer med højreklik eller ctrl-klik:','Writing of the exported settings failed.'=>'Skrivning af de eksporterede indstillinger mislykkedes.','The groups have been sorted alphabetically.'=>'Grupperne er blevet sorteret alfabetisk.','The label cannot be empty.'=>'Mærket kan ikke være tomt.','A tag group with the label \'%s\' already exists, or the label has not changed. Please choose another one or go back.'=>'En taggruppe med mærket \'%s\' eksisterer allerede, eller mærket er ikke ændret. Vælg venligst et andet eller gå tilbage.','A new tag group with the label \'%s\' has been created!'=>'En ny taggruppe med mærket \'%s\' er blevet oprettet!','A tag group with the label \'%s\' already exists.'=>'En taggruppe med mærket \'%s\' eksisterer allerede.','The tag group with the label \'%s\' has been saved!'=>'Taggruppen med mærket \'%s\' er blevet gemt!','A tag group with the id %1$s and the label \'%2$s\' has been deleted.'=>'En taggruppe med id %1$s og mærket \'%2$s\' er blevet slettet.','Error uploading the file.'=>'Fejl ved upload af filen.','Error reading the file.'=>'Fejl ved læsning af filen.','Error parsing the file.'=>'Fejl ved fortolkning af filen.','date unknown'=>'dato ukendt','Your settings and groups have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Dine indstillinger og grupper er blevet importeret fra filen %1$s (oprettet med plugin-version %2$s den %3$s).','%d option was added or changed.'=>'%d mulighed blev tilføjet eller ændret.' . "\0" . '%d muligheder blev tilføjet eller ændret.','Your terms have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Dine termer er blevet importeret fra filen %1$s (oprettet med plugin-version %2$s den %3$s).','We processed %d term.'=>'Vi har behandlet %d term.' . "\0" . 'Vi har behandlet %d termer.','We saved %d term.'=>'Vi har gemt %d term.' . "\0" . 'Vi har gemt %d termer.','The group info of %d term was updated.'=>'Gruppens info for %d term blev opdateret.' . "\0" . 'Gruppens info for %d termer blev opdateret.','Filters'=>'Filtre','Gutenberg'=>'Gutenberg','Multilingual'=>'Flersproget','Shortcodes'=>'Kortkoder','Themes and Appearance'=>'Temaer og Udseende','remove'=>'fjern','(recommended)'=>'(anbefalet)','keep'=>'behold','use unfiltered_html filter'=>'brug unfiltered_html filter','First Aid'=>'Førstehjælp','REST API'=>'REST API','System Information'=>'Systeminformation','Debugging'=>'Fejlfinding','Export/Import'=>'Eksport/Import','Reset'=>'Nulstil','Licences'=>'Licenser','Transients'=>'Transienter','Database'=>'Database','Filesystem'=>'Filsystem','WP Object Cache'=>'WP Objekt Cache','Your settings have been saved.'=>'Dine indstillinger er blevet gemt.','Your settings has been saved.'=>'Dine indstillinger er blevet gemt.','All groups have been deleted and assignments reset.'=>'Alle grupper er blevet slettet og tildelinger nulstillet.','The filter on the tags page has been reset to show all tags.'=>'Filteret på tagsiden er blevet nulstillet for at vise alle tags.','tag groups'=>'tag grupper','tag cloud'=>'tag sky','group info'=>'gruppe info','sidebar widget'=>'sidebar widget','accordion'=>'accordion','tabs'=>'faner','alphabetical'=>'alfabetisk','post list'=>'indlægsliste','colors'=>'farver','tag description'=>'tag beskrivelse','tag filter'=>'tag filter','post filter'=>'indlæg filter','backup'=>'backup','remove plugin'=>'fjern plugin','remove data'=>'fjern data','delete groups'=>'slet grupper','debugging'=>'fejlfinding','PHP Version'=>'PHP Version','Ajax Test'=>'Ajax Test','troubleshooting'=>'fejlretning','benchmarks'=>'benchmarks','speed test'=>'hastighedstest','error'=>'fejl','testing'=>'testning','help'=>'hjælp','Tag Groups Pro'=>'Tag Grupper Pro','upgrade'=>'opgrader','more groups'=>'flere grupper','posts'=>'indlæg','filter'=>'filter','animated'=>'animeret','searchable'=>'søgbar','Info'=>'Info','author'=>'forfatter','version'=>'version','contact'=>'kontakt','about'=>'om','Licenses'=>'Licenser','Credits'=>'Kreditter','Development News'=>'Udviklingsnyheder','blog'=>'blog','updates'=>'opdateringer','getting started'=>'komme i gang','introduction'=>'introduktion','sample'=>'eksempel','migrate'=>'migrere','problem'=>'problem','live block preview'=>'live blok forhåndsvisning','translation'=>'oversættelse','Migrating the term meta'=>'Migrering af termen meta','Fixing incorrect tag groups'=>'Retting af forkerte taggrupper','Fixing incorrect groups in term meta'=>'Retting af forkerte grupper i termen meta','Sorting groups in term meta'=>'Sortering af grupper i termen meta','Checking the tag names'=>'Kontrollere tag-navnene','Start'=>'Start','Sample Content'=>'Eksempelindhold','Sample Group A'=>'Eksempelgruppe A','Sample Group B'=>'Eksempelgruppe B','Sample Group C'=>'Eksempelgruppe C','First Sample Tag'=>'Første eksempel-tag','Second Sample Tag'=>'Andet eksempel tag','Third Sample Tag'=>'Tredje eksempel tag','Create a draft sample page with Gutenberg blocks.'=>'Opret en kladdeprøveside med Gutenberg blokke.','Create a draft sample page with shortcodes.'=>'Opret en kladdeprøveside med shortcodes.','The plugin %1$s requires WordPress %2$s to function properly.'=>'Plugin\'et %1$s kræver WordPress %2$s for at fungere korrekt.','Please upgrade WordPress and then try again.'=>'Opgrader venligst WordPress og prøv igen.','not assigned'=>'ikke tildelt','You\'re using Tag Groups Free. The Pro version has more features and support. %sUpgrade to Pro%s'=>'Du bruger Tag Groups Free. Pro-versionen har flere funktioner og support. %sOpgrader til Pro%s','Upgrade to Pro'=>'Opgrader til Pro','Upgrade to Tag Groups Pro'=>'Opgrader til Tag Groups Pro','Enhance the power of Tag Groups with the Pro version:'=>'Forstærk kraften i Tag Groups med Pro-versionen:','21 Shortcodes'=>'21 Shortcodes','18 Gutenberg Blocks'=>'18 Gutenberg Blokke','Table Tag Cloud'=>'Tabel Tag Cloud','Simple Tag Cloud'=>'Simpel Tag Cloud','Shuffle Box'=>'Blandingsboks','Caching'=>'Caching','Multiple Groups Per Tag'=>'Flere grupper pr. tag','Tag Cloud Search'=>'Tag Cloud Søgning','Toggle Post Filter'=>'Skift postfilter','Dynamic Post Filter'=>'Dynamisk Postfilter','Post List'=>'Postliste','Tag Meta Box'=>'Tag Meta Box','Post Tags in Groups'=>'Posttags i Grupper','Permissions'=>'Tilladelser','Default Groups'=>'Standardgrupper','WooCommerce Attributes'=>'WooCommerce Attributter','Parent Group Level'=>'Overordnet Gruppe Niveau','Need Tag Groups Support?'=>'Har du brug for støtte til Tag Grupper?','If you need help or have a new feature request, let us know.'=>'Hvis du har brug for hjælp eller har en ny funktionsanmodning, så lad os vide det.','Request Support'=>'Anmod om Support','Detailed documentation is also available on the plugin website.'=>'Detaljeret dokumentation er også tilgængelig på plugin-webstedet.','View Knowledge Base'=>'Se Vidensbase','The free Tag Groups plugin cannot be active together with Tag Groups Pro.'=>'Det gratis Tag Grupper plugin kan ikke være aktivt sammen med Tag Grupper Pro.','more information'=>'mere information','Edit tag groups'=>'Rediger taggrupper','Clicking will leave this page without saving.'=>'Klikker du, forlader du denne side uden at gemme.','Welcome to %s!'=>'Velkommen til %s!','The plugin is ready for use. If you need some assistance, we can walk you through the basic steps.'=>'Plugin\'et er klar til brug. Hvis du har brug for hjælp, kan vi guide dig gennem de grundlæggende trin.','Start the Setup Wizard'=>'Start Opsætningsguiden','Or click here if you prefer to do it on your own.'=>'Eller klik her, hvis du foretrækker at gøre det selv.','Go to the <span class="dashicons dashicons-tag"></span>&nbsp;Tag Groups <a %s>taxonomy settings</a> and <b>select the taxonomy</b> (tag type) of your tags. In most cases just leave the default: Tags (post_tag).'=>'Gå til <span class="dashicons dashicons-tag"></span>&nbsp;Tag Groups <a %s>taxonomyindstillinger</a> og <b>vælg taxonomy</b> (tagtype) for dine tags. I de fleste tilfælde skal du blot lade standarden være: Tags (post_tag).','Go to the tag groups admin page and <b>create some groups</b>.'=>'Gå til taggruppens adminside og <b>opret nogle grupper</b>.','You can find these pages listed on your <a %s>Tag Groups home page</a>.'=>'Du kan finde disse sider opført på din <a %s>Tag Groups startside</a>.','Go to your tags and <b>assign them to these groups</b>.'=>'Gå til dine tags og <b>tildel dem til disse grupper</b>.','Filter by tag group'=>'Filtrer efter taggruppe','%s created this sample page in the Setup Wizard of the <b>Tag Groups</b> plugin. You can safely edit and delete it or keep it for future reference.'=>'%s oprettede denne prøve side i Setup Wizard for <b>Tag Groups</b> plugin. Du kan trygt redigere og slette den eller gemme den til fremtidig reference.','The following shortcodes use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'De følgende kortkoder bruger en række parametre, så du kan få en idé om mulighederne. Du er velkommen til at generere en ny prøveside med flere funktioner efter opgradering af plugin.','Please find links to the documentation in the <a %s>Tag Groups settings</a>.'=>'Find venligst links til dokumentationen i <a %s>Tag Groups indstillinger</a>.','Tabbed Tag Cloud'=>'Fanebladet Tag Cloud','Accordion Tag Cloud'=>'Accordion Tag Cloud','Alphabetical Tag Cloud'=>'Alfabetisk Tag Cloud','Tag List'=>'Tagliste','Alphabetical Tag Index'=>'Alfabetisk Tagindeks','The following blocks use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'De følgende blokke bruger en række parametre, så du kan få en idé om mulighederne. Du er velkommen til at generere en ny prøveside med flere funktioner efter opgradering af plugin.','This page was created while you had the Gutenberg editor enabled. Therefore the features only display while Gutenberg is active.'=>'Denne side blev oprettet, mens du havde Gutenberg-editoren aktiveret. Derfor vises funktionerne kun, mens Gutenberg er aktiv.','Display filter on the "Posts" screen.'=>'Vis filter på "Indlæg"-skærmen.','Add a pull-down menu to the filters above the list of posts. If you filter posts by tag groups, then only items will be shown that have tags (terms) in that particular group. This feature can be turned off so that the menu won\'t obstruct your screen if you use a high number of groups. May not work with all taxonomies.'=>'Tilføj en rullemenu til filtrene over listen med indlæg. Hvis du filtrerer indlæg efter taggrupper, vil der kun blive vist elementer, der har tags (termer) i den pågældende gruppe. Denne funktion kan slås fra, så menuen ikke forstyrrer din skærm, hvis du bruger et stort antal grupper. Måske ikke fungerer med alle taxonomier.','Display filter on the "Tags" screen.'=>'Vis filter på "Tags"-skærmen.','Add a filter to the list of tags. Disable it here if it conflicts with other plugins or themes.'=>'Tilføj et filter til listen over tags. Deaktiver det her, hvis det konflikter med andre plugins eller temaer.','Save Settings'=>'Gem indstillinger','Gutenberg block preview'=>'Gutenberg blok forhåndsvisning','Some blocks can show an approximate preview in the Gutenberg editor. If you deactivate this option, then all blocks will show a static icon with text.'=>'Nogle blokke kan vise en omtrentlig forhåndsvisning i Gutenberg-editoren. Hvis du deaktiverer denne mulighed, vil alle blokke vise et statisk ikon med tekst.','Keep groups of translations in sync'=>'Hold grupper af oversættelser synkroniseret','If you activate this option, we try to sync the groups across all language versions of a tag when you save it. Deactivate it to set groups independently.'=>'Hvis du aktiverer denne mulighed, prøver vi at synkronisere grupperne på tværs af alle sprogversioner af en tag, når du gemmer det. Deaktiver det for at indstille grupper uafhængigt.','All Tag Groups features are available as Gutenberg blocks. You can also use shortcodes.'=>'Alle taggruppers funktioner er tilgængelige som Gutenberg blokke. Du kan også bruge shortcodes.','Click on the features for more information.'=>'Klik på funktionerne for mere information.','Display the tags in a tabbed tag cloud.'=>'Vis tags i en fanebaseret tag-sky.','Example'=>'Eksempel','Parameters'=>'Parametre','Please find the parameters in the <a %s>documentation</a>.'=>'Find venligst parametrene i <a %s>dokumentationen</a>.','Accordion'=>'Accordion','Display the tags in an accordion.'=>'Vis tags i et accordion.','Display the tags in lists under tag groups.'=>'Vis tags i lister under taggrupper.','Display the tags in tabbed tag cloud with first letters as tabs.'=>'Vis tags i en fanebaseret tag-sky med første bogstaver som faner.','(Not tested with right-to-left languages.)'=>'(Ikke testet med sprog fra højre til venstre.)','Display the tags in a list with first letters as heading.'=>'Vis tags i en liste med første bogstaver som overskrift.','Group Information'=>'Gruppeinformation','Display information about tag groups.'=>'Vis information om taggrupper.','The function <b>tag_groups_cloud</b> accepts the same parameters as the [tag_groups_cloud] shortcode, except for those that determine tabs and styling.'=>'Funktionen <b>tag_groups_cloud</b> accepterer de samme parametre som [tag_groups_cloud] shortcode, undtagen dem der bestemmer faner og styling.','By default it returns a string with the html for a tabbed tag cloud.'=>'Som standard returnerer den en streng med HTML til en fanebaseret tag-sky.','If the optional second parameter is set to \'true\', the function returns a multidimensional array containing tag groups and tags.'=>'Hvis den valgfri anden parameter er indstillet til \'true\', returnerer funktionen et multidimensionelt array, der indeholder tag-grupper og tags.','Enable shortcode in sidebar widgets (if not visible anyway).'=>'Aktivér shortcode i sidebar widgets (hvis ikke synlig alligevel).','Always load shortcode scripts.'=>'Indlæs altid shortcode scripts.','Click for more information'=>'Klik for mere information','Turn off to load the scripts only on posts and pages where a shortcode appears.'=>'Slå fra for kun at indlæse scripts på indlæg og sider, hvor en shortcode vises.','Turn on if you use these shortcodes in widgets.'=>'Tænd for, hvis du bruger disse shortcodes i widgets.','Here you can choose a theme for the Tabbed Tag Cloud and the Accordion Tag Cloud.'=>'Her kan du vælge et tema til den fanebaserede tag-sky og den akustiske tag-sky.','New themes can be created with the <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:'=>'Nye temaer kan oprettes med <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:','On the page "Theme Roller" you can customize all features or pick one set from the gallery. Finish with the "download" button.'=>'På siden "Theme Roller" kan du tilpasse alle funktioner eller vælge et sæt fra galleriet. Afslut med "download" knappen.','On the next page ("Download Builder") you will need to select the version 1.12.x and the components "Widget", "Accordion" and "Tabs". Make sure that before downloading you enter at the bottom as "CSS Scope" <b>.tag-groups-cloud</b> (including the dot).'=>'På den næste side ("Download Builder") skal du vælge version 1.12.x og komponenterne "Widget", "Accordion" og "Tabs". Sørg for, at du inden download indtaster "CSS Scope" nedenfor som <b>.Tag-Groups</b> (inklusive punktummet).','Then you unpack the downloaded zip file. You will need the "images" folder and the "jquery-ui.theme.min.css" file.'=>'Derefter pakker du den downloaded zip-fil ud. Du skal bruge "images" mappen og filen "jquery-ui.theme.min.css".','Create a new folder inside your <i>wp-content/uploads</i> folder (for example "my-theme") and copy there these two items.'=>'Opret en ny mappe inde i din <i>wp-content/uploads</i> mappe (for eksempel "my-theme") og kopier disse to elementer derind.','Enter the name of this new folder (for example "my-theme") below.'=>'Indtast navnet på denne nye mappe (for eksempel "my-theme") nedenfor.','own theme'=>'Eget tema','Don\'t load a theme.'=>'Indlæs ikke et tema.','Here you can turn off jQuery UI themes if your WordPress theme brings its own jQuery UI theme, in order to avoid conflicts.'=>'Her kan du deaktivere jQuery UI temaer, hvis dit WordPress tema medbringer sit eget jQuery UI tema, for at undgå konflikter.','Further options'=>'Yderligere muligheder','Use jQuery.  (Default is on. Other plugins might override this setting.)'=>'Brug jQuery. (Standard er aktiv. Andre plugins kan overskrive denne indstilling.)','Tabs triggered by hovering mouse pointer (without clicking).'=>'Faner udløst ved at føre musen over (uden at klikke).','Collapsible tabs (toggle open/close).'=>'Kollapsbare faner (skift åbne/lukke).','HTML in tag description:'=>'HTML i tagbeskrivelse:','By default the description appears in a tooltip when you hover the mouse over a tag in a tag cloud.'=>'Som standard vises beskrivelsen i en tooltip, når du holder musen over et tag i en tag cloud.','If you don\'t trust all users of your site, remove the HTML or use a plugin to give the unfiltered_html capability only to users you trust.'=>'Hvis du ikke stoler på alle brugere af din side, skal du fjerne HTML eller bruge et plugin til kun at give unfiltered_html kapabiliteten til brugere, du stoler på.','Save Theme Options'=>'Gem temaindstillinger','Search for settings'=>'Søg efter indstillinger','Search for setting pages. Type a space to show all settings.'=>'Søg efter indstillings sider. Skriv et mellemrum for at vise alle indstillinger.','Search Results'=>'Søgeresultater','Nothing found'=>'Intet fundet','Active Taxonomies'=>'Aktive Taxonomies','Group Statistics'=>'Gruppe Statistik','for the selected language'=>'for det valgte sprog','go to tag group administration'=>'gå til tag gruppe administration','Enable Tag Groups Public API Access'=>'Aktiver Tag-Groups offentlig API-adgang','Enable public access to tag groups endpoint /wp-json/tag-groups/v1/groups/.'=>'Aktiver offentlig adgang til tag grupper endpoint /wp-json/tag-groups/v1/groups/.','Enable Terms Public API Access'=>'Aktiver Vilkår offentlig API-adgang','Enable public access to terms endpoint /wp-json/tag-groups/v1/terms/.'=>'Aktiver offentlig adgang til vilkår endpoint /wp-json/tag-groups/v1/terms/.','Choose the taxonomies for which you want to use Tag Groups:'=>'Vælg de taxonomies, som du vil bruge Tag-Groups til:','The default texonomy is <b>Tags (post_tag)</b>. Please note that the tag clouds might not work with all taxonomies and that some taxonomies listed here may not be accessible in the admin backend. If you don\'t understand what is going on here, just leave the default.'=>'Den standard taxonomy er <b>Tags (post_tag)</b>. Bemærk venligst, at tag clouds muligvis ikke fungerer med alle taxonomies, og at nogle taxonomies, der er nævnt her, muligvis ikke er tilgængelige i admin backend. Hvis du ikke forstår, hvad der sker her, skal du bare lade standarden være.','<b>Please deselect taxonomies that you don\'t use. Using several taxonomies for the same post type or hierarchical taxonomies (like categories) is experimental and not supported.</b>'=>'<b>Vær venlig at fravælge taxonomies, som du ikke bruger. At bruge flere taxonomies til den samme post type eller hierarkiske taxonomies (som kategorier) er eksperimentelt og ikke understøttet.</b>','To see the post type, hover your mouse over the option.'=>'For at se posttypen, hold musen over muligheden.','If you use a custom taxonomy, make sure that the attribute "Public" is set to "true" and "Hierarchical" to "false".'=>'Hvis du bruger en brugerdefineret taxonomy, skal du sørge for, at attributten "Public" er indstillet til "true" og "Hierarchical" til "false".','Show hierarchical taxonomies. Not all Tag Groups features will work with these taxonomies.'=>'Vis hierarkiske taxonomier. Ikke alle Tag Groups funktioner vil fungere med disse taxonomier.','Save Taxonomies'=>'Gem taxonomier','Export'=>'Eksporter','Use this button to export all Tag Groups settings and groups and all terms that are assigned to a group into files.'=>'Brug denne knap til at eksportere alle Tag Groups indstillinger og grupper samt alle termer, der er tildelt en gruppe, til filer.','You can import both files separately. Category hierarchy won\'t be saved. When you restore terms that were deleted, they receive new IDs and you must assign them to posts again. Exporting cannot substitute a backup.'=>'Du kan importere begge filer separat. Kategori hierarkiet vil ikke blive gemt. Når du gendanner termer, der blev slettet, modtager de nye ID\'er, og du skal tildele dem til indlæg igen. Eksportering kan ikke erstatte en backup.','Export Files'=>'Eksportér filer','Import'=>'Importer','Below you can import previously exported settings/groups or terms from a file.'=>'Nedenfor kan du importere tidligere eksporterede indstillinger/grupper eller termer fra en fil.','It is recommended to back up the database of your site before proceeding.'=>'Det anbefales at tage backup af databasen på din side, før du fortsætter.','Please import the settings before the terms.'=>'Venligst importer indstillingerne før termerne.','Import File'=>'Importer fil','Use this button to delete all tag groups and assignments. Your tags will not be changed. Check the checkbox to confirm.'=>'Brug denne knap til at slette alle taggrupper og tildelinger. Dine tags vil ikke blive ændret. Marker afkrydsningsfeltet for at bekræfte.','Please keep in mind that the tag assignments cannot be recovered by the export/import function.'=>'Bemærk venligst, at tagtildelinger ikke kan gendannes ved hjælp af eksport/import funktionen.','I know what I am doing.'=>'Jeg ved, hvad jeg laver.','Delete Groups'=>'Slet grupper','Delete Settings and Groups'=>'Slet indstillinger og grupper','Delete all groups and settings when uninstalling the plugin.'=>'Slet alle grupper og indstillinger, når du afinstallerer plugin\'et.','Debug mode is on.'=>'Debug-tilstand er aktiveret.','Verbose logging is enabled with CM_DEBUG.'=>'Verbose logging er aktiveret med CM_DEBUG.','Verbose logging is on.'=>'Verbose logging er tændt.','Turn off '=>'Sluk for ','Verbose logging is off.'=>'Verbose logging er slukket.','Turn on'=>'Tænd for','Debug mode is off.'=>'Debug-tilstand er slukket.','Learn more <a %s>about debugging</a>.'=>'Lær mere <a %s>om fejlfinding</a>.','Migrate tags to the new format of Tag Groups.'=>'Migrer tags til det nye format af Tag Groups.','The plugin automatically migrates tags to the new format and tries to keep track of changes. There may, however, be cases where other components made unnoticed changes. You might also need to manually migrate tags after you enabled a taxonomy that already contained untracked tags.'=>'Pluginet migrerer automatisk tags til det nye format og forsøger at holde styr på ændringer. Der kan dog være tilfælde, hvor andre komponenter har foretaget uopdagede ændringer. Du kan også være nødt til manuelt at migrere tags, efter du har aktiveret en taksonomi, der allerede indeholdt uregistrerede tags.','Migrate'=>'Migrer','Running the maintenance can solve issues that you encounter during filtering by tag groups.'=>'Kør vedligeholdelse kan løse problemer, du støder på under filtrering efter taggrupper.','Maintenance'=>'Vedligeholdelse','Reset the filter on the tags page to show all tags.'=>'Nulstil filteret på tags siden for at vise alle tags.','Use it if a JavaScript error disables the filter menu. Note that it is still recommended to find out the cause of the error.'=>'Brug det, hvis en JavaScript-fejl deaktiverer filtermenuen. Bemærk, at det stadig anbefales at finde årsagen til fejlen.','Reset Tag Filter'=>'Nulstil Tag Filter','Please stay on this page until all processes have finished.'=>'Forbliv venligst på denne side, indtil alle processer er færdige.','There have been errors.'=>'Der har været fejl.','Continue'=>'Fortsæt','Finished!'=>'Færdig!','The following terms cannot be used:'=>'Følgende vilkår kan ikke bruges:','Number of processed items: '=>'Antal behandlede elementer: ','Number of changed items: '=>'Antal ændrede elementer: ','WordPress Version'=>'WordPress Version','Site URL'=>'Site URL','Home URL'=>'Hjemmeside URL','Active Theme'=>'Aktiv Tema','Version'=>'Version','Checking...'=>'Tjekker...','Show the Response'=>'Vis svaret','passed'=>'bestået','failed'=>'fejlet','Benchmarks'=>'Benchmarking','Cache'=>'Cache','Tag groups pro only'=>'Taggrupper kun pro','Server'=>'Server','Constants'=>'Konstanter','Well done!'=>'Godt klaret!','Now go the Tag Group Administration.'=>'Gå nu til Taggruppeadministrationen.','Or preview the sample page here.'=>'Eller forhåndsvis prøvesiden her.','Or go to the <a %s>Tag Groups settings</a> or visit the <a %s>documentation</a>.'=>'Eller gå til <a %s>indstillinger for Taggrupper</a> eller besøg <a %s>dokumentationen</a>.','Now go to the <a %s>Tag Groups settings</a>, or visit the <a %s>documentation</a>.'=>'Gå nu til <a %s>Tag Grupper indstillinger</a>, eller besøg <a %s>dokumentationen</a>.','If you need to launch the Setup Wizard again, you can find it in the settings. Just enter "wizard" in the search field.'=>'Hvis du har brug for at starte Opsætningsguiden igen, kan du finde den i indstillingerne. Indtast blot "wizard" i søgefeltet.','Happy tagging!'=>'God tagging!','Tag Groups Setup Wizard'=>'Tag Grupper Opsætningsguide','Now you are ready to create your own tag groups. If you prefer to start out from a sample, we will create for you three groups and three tags. You can play around with them, rename or delete them.'=>'Nu er du klar til at oprette dine egne tag grupper. Hvis du foretrækker at starte fra et eksempel, vil vi oprette tre grupper og tre tags til dig. Du kan lege med dem, omdøbe eller slette dem.','Create sample groups:'=>'Opret eksempel grupper:','Create sample tags in these groups:'=>'Opret eksempel tags i disse grupper:','Next Step'=>'Næste trin','On the following pages we will guide you through the basic settings that you need for the most common features.'=>'På de følgende sider vil vi guide dig gennem de grundlæggende indstillinger, som du har brug for til de mest almindelige funktioner.','You can later make changes or fine-tune the details in the Tag Groups settings.'=>'Du kan senere foretage ændringer eller finjustere detaljerne i Tag Grupper indstillinger.','(show me the menu)'=>'(vis mig menuen)','Feel free to abort the Setup Wizard any time and continue on your own path. You can also launch it again at a later time.'=>'Du er velkommen til at afbryde Opsætningsguiden når som helst og fortsætte ad din egen vej. Du kan også starte den igen på et senere tidspunkt.','The wizard will offer more options after upgrading to premium.'=>'Guiden vil tilbyde flere muligheder efter opgradering til premium.','Choose the taxonomies for which you want to use tag groups.'=>'Vælg de taxonomies, som du vil bruge tag grupper til.','In most cases the default taxonomy <b>Tags (post_tag)</b> will do the job.'=>'I de fleste tilfælde vil den standard taxonomy <b>Tags (post_tag)</b> gøre jobbet.','post type'=>'post type','You will find more options in the Tag Groups settings.'=>'Du vil finde flere muligheder i Tag Grupper indstillinger.','Tag Group Administration'=>'Tag Gruppe Administration','Filter by label'=>'Filtrer efter etikette','Tag Group name'=>'Tag Gruppe navn','Number of assigned tags'=>'Antal tildelte tags','Actions'=>'Handlinger','Change order'=>'Ændr rækkefølge','Group ID'=>'Gruppe ID','Edit'=>'Rediger','Create'=>'Opret','new'=>'ny','label'=>'etiket','Delete this group.'=>'Slet denne gruppe.','Create a new group below.'=>'Opret en ny gruppe nedenfor.','Add New Tag Group'=>'Tilføj ny taggruppe','move up'=>'flyt op','move down'=>'flyt ned','reload'=>'genindlæs','next page'=>'næste side','previous page'=>'forrige side','go to page:'=>'gå til side:','Show posts'=>'Vis indlæg','Show tags'=>'Vis tags','Do you really want to delete this tag group?'=>'Vil du virkelig slette denne taggruppe?','Please visit <a %s>%s</a>.'=>'Besøg venligst <a %s>%s</a>.','Read more'=>'Læs mere','Thanks for using Tag Groups | %1sTaxoPress.com%2s | Version %3s'=>'Tak for at bruge Tag Grupper | %1sTaxoPress.com%2s | Version %3s','Assign to'=>'Tildel til','Filter off'=>'Filter fra','Please select one of the languages above to see the correct tag groups!'=>'Vælg venligst et af de ovenstående sprog for at se de korrekte taggrupper!','Groups'=>'Grupper','You\'re using Tag Groups Free. The Pro version has more features and support. %1$sUpgrade to Pro%2$s'=>'Du bruger Tag Grupper Gratis. Pro versionen har flere funktioner og support. %1$sOpgrader til Pro%2$s','Or go to the <a %1$s>Tag Groups settings</a> or visit the <a %2$s>documentation</a>.'=>'Eller gå til <a %1$s>Tag Grupper indstillinger</a> eller besøg <a %2$s>dokumentationen</a>.','Now go to the <a %1$s>Tag Groups settings</a>, or visit the <a %2$s>documentation</a>.'=>'Gå nu til <a %1$s>Tag Grupper indstillinger</a>, eller besøg <a %2$s>dokumentationen</a>.','Please visit <a %1$s>%2$s</a>.'=>'Besøg venligst <a %1$s>%2$s</a>.','Thanks for using Tag Groups | %1$sTaxoPress.com%2$s | Version %3$s'=>'Tak for at bruge Tag Grupper | %1$sTaxoPress.com%2$s | Version %3$s']];